'use client';

import React, { useState, useRef } from 'react';
import { ArrowRightIcon, ArrowLeftIcon, DocumentTextIcon, PhotoIcon, VideoCameraIcon, XMarkIcon, PlusIcon } from '@heroicons/react/24/outline';
import type { ProjectFormData } from '../page';
import { supabase } from '../../../../lib/supabase';

interface ProjectDetailsProps {
  formData: ProjectFormData;
  updateFormData: (data: Partial<ProjectFormData>) => void;
  onNext: () => void;
  onBack: () => void;
}

const imageCategories = ['Exterior', 'Interior', 'Amenities', 'Floor Plans', 'Location', 'Construction Updates'];

const ProjectDetails: React.FC<ProjectDetailsProps> = ({ formData, updateFormData, onNext, onBack }) => {
  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [uploading, setUploading] = useState<boolean>(false);
  const [uploadStatus, setUploadStatus] = useState<{ type: 'success' | 'error', message: string } | null>(null);
  const [activeCategory, setActiveCategory] = useState<string>(imageCategories[0]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverImageInputRef = useRef<HTMLInputElement>(null);
  const brochureInputRef = useRef<HTMLInputElement>(null);

  const validate = () => {
    const newErrors: { [key: string]: string } = {};
    if (!formData.description.trim()) newErrors.description = 'Project description is required.';
    if (!formData.project_highlights.length || formData.project_highlights.every(h => !h.trim())) newErrors.project_highlights = 'At least one project highlight is required.';
    if (!formData.emi_details.amount || !formData.emi_details.duration || !formData.emi_details.interest_rate) newErrors.emi_details = 'All EMI details are required.';
    if (!formData.cover_image_url) newErrors.cover_image = 'Cover image is required.';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    if (name === 'description') {
      updateFormData({ description: value });
    } else if (name === 'project_highlights') {
      updateFormData({ project_highlights: value.split('\n').map(h => h.trim()).filter(Boolean) });
    } else if (name === 'video_url') {
      updateFormData({ video_url: value });
    } else if (name.startsWith('emi_details.')) {
      updateFormData({
        emi_details: {
          ...formData.emi_details,
          [name.split('.')[1]]: parseFloat(value) || 0,
        },
      });
    }
  };

  const handleUploadCoverImage = async (file: File) => {
    if (!file) return;
    
    setUploading(true);
    setUploadStatus(null);
    
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `cover-${Date.now()}.${fileExt}`;
      const filePath = `${fileName}`;
      
      const { error: uploadError } = await supabase.storage
        .from('project_images')
        .upload(filePath, file, { upsert: true });
        
      if (uploadError) {
        throw uploadError;
      }
      
      const { data } = supabase.storage
        .from('project_images')
        .getPublicUrl(filePath);
        
      updateFormData({ cover_image_url: data.publicUrl });
      setUploadStatus({ type: 'success', message: 'Cover image uploaded successfully' });
    } catch (error) {
      console.error('Error uploading cover image:', error);
      setUploadStatus({ type: 'error', message: 'Failed to upload cover image' });
    } finally {
      setUploading(false);
    }
  };

  const handleUploadBrochure = async (file: File) => {
    if (!file) return;
    
    setUploading(true);
    setUploadStatus(null);
    
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `brochure-${Date.now()}.${fileExt}`;
      const filePath = `${fileName}`;
      
      const { error: uploadError } = await supabase.storage
        .from('project_documents')
        .upload(filePath, file, { upsert: true });
        
      if (uploadError) {
        throw uploadError;
      }
      
      const { data } = supabase.storage
        .from('project_documents')
        .getPublicUrl(filePath);
        
      updateFormData({ brochure_url: data.publicUrl });
      setUploadStatus({ type: 'success', message: 'Brochure uploaded successfully' });
    } catch (error) {
      console.error('Error uploading brochure:', error);
      setUploadStatus({ type: 'error', message: 'Failed to upload brochure' });
    } finally {
      setUploading(false);
    }
  };

  const handleUploadProjectImage = async (file: File) => {
    if (!file) return;
    
    setUploading(true);
    setUploadStatus(null);
    
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${activeCategory.toLowerCase().replace(/\s+/g, '-')}-${Date.now()}.${fileExt}`;
      const filePath = `${fileName}`;
      
      const { error: uploadError } = await supabase.storage
        .from('project_images')
        .upload(filePath, file, { upsert: true });
        
      if (uploadError) {
        throw uploadError;
      }
      
      const { data } = supabase.storage
        .from('project_images')
        .getPublicUrl(filePath);
        
      // Add the new image to the project_images array
      const newImage = {
        url: data.publicUrl,
        category: activeCategory
      };
      
      updateFormData({ 
        project_images: [...formData.project_images, newImage]
      });
      
      setUploadStatus({ type: 'success', message: 'Project image uploaded successfully' });
    } catch (error) {
      console.error('Error uploading project image:', error);
      setUploadStatus({ type: 'error', message: 'Failed to upload project image' });
    } finally {
      setUploading(false);
    }
  };

  const removeProjectImage = (imageUrl: string) => {
    const updatedImages = formData.project_images.filter(img => img.url !== imageUrl);
    updateFormData({ project_images: updatedImages });
  };

  const handleNext = (e: React.FormEvent) => {
    e.preventDefault();
    if (validate()) onNext();
  };

  return (
    <form onSubmit={handleNext} className="space-y-8">
      {/* Project Media Section */}
      <div>
        <h3 className="text-lg font-medium text-gray-900 mb-4">Project Media</h3>
        <div className="space-y-6">
          {/* Cover Image Upload */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Cover Image <span className="text-red-500">*</span></label>
            <div className="mt-1 flex flex-col items-center">
              {formData.cover_image_url ? (
                <div className="relative w-full">
                  <img 
                    src={formData.cover_image_url} 
                    alt="Cover" 
                    className="h-60 w-full object-cover rounded-lg"
                  />
                  <button
                    type="button"
                    onClick={() => updateFormData({ cover_image_url: '' })}
                    className="absolute top-2 right-2 bg-white rounded-full p-1 shadow-md text-red-500 hover:text-red-700"
                  >
                    <XMarkIcon className="w-5 h-5" />
                  </button>
                </div>
              ) : (
                <div 
                  className="w-full h-60 border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center cursor-pointer hover:bg-gray-50"
                  onClick={() => coverImageInputRef.current?.click()}
                >
                  <PhotoIcon className="w-12 h-12 text-gray-400" />
                  <span className="mt-2 text-sm text-gray-500">Click to upload cover image</span>
                </div>
              )}
              <input
                ref={coverImageInputRef}
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => {
                  if (e.target.files && e.target.files[0]) {
                    handleUploadCoverImage(e.target.files[0]);
                  }
                }}
              />
              {errors.cover_image && <p className="text-xs text-red-500 mt-1">{errors.cover_image}</p>}
            </div>
          </div>

          {/* Video URL */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Video URL</label>
            <div className="mt-1 relative">
              <VideoCameraIcon className="w-5 h-5 absolute left-3 top-3 text-gray-400" />
              <input
                type="text"
                name="video_url"
                value={formData.video_url}
                onChange={handleChange}
                className="pl-10 pr-3 py-2 w-full rounded-lg border border-gray-300 focus:ring-green-500 focus:border-green-500"
                placeholder="YouTube or Vimeo URL"
              />
            </div>
          </div>

          {/* Project Images */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Project Images</label>
            
            {/* Category Tabs */}
            <div className="mb-4">
              <div className="flex space-x-1 overflow-x-auto pb-2">
                {imageCategories.map(category => (
                  <button
                    key={category}
                    type="button"
                    className={`px-3 py-1.5 text-xs rounded-lg whitespace-nowrap ${
                      activeCategory === category
                        ? 'bg-green-600 text-white'
                        : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                    }`}
                    onClick={() => setActiveCategory(category)}
                  >
                    {category}
                  </button>
                ))}
              </div>
            </div>
            
            {/* Image Gallery for Current Category */}
            <div>
              <h4 className="text-sm font-medium text-gray-700 mb-2">{activeCategory} Images</h4>
              
              <div className="grid grid-cols-2 md:grid-cols-3 gap-4 mb-4">
                {formData.project_images
                  .filter(img => img.category === activeCategory)
                  .map((image, index) => (
                    <div key={index} className="relative group">
                      <img
                        src={image.url}
                        alt={`${activeCategory} ${index + 1}`}
                        className="h-32 w-full object-cover rounded-lg"
                      />
                      <button
                        type="button"
                        onClick={() => removeProjectImage(image.url)}
                        className="absolute top-1 right-1 bg-white rounded-full p-1 shadow-md text-red-500 hover:text-red-700 opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <XMarkIcon className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                
                {/* Upload Button */}
                <div
                  className="h-32 border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center cursor-pointer hover:bg-gray-50"
                  onClick={() => fileInputRef.current?.click()}
                >
                  <PlusIcon className="w-8 h-8 text-gray-400" />
                  <span className="mt-1 text-xs text-gray-500">Add Image</span>
                </div>
              </div>
              
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => {
                  if (e.target.files && e.target.files[0]) {
                    handleUploadProjectImage(e.target.files[0]);
                  }
                }}
              />
            </div>
          </div>

          {/* Brochure Upload */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Project Brochure</label>
            <div className="mt-1 flex items-center">
              {formData.brochure_url ? (
                <div className="flex items-center space-x-2">
                  <a 
                    href={formData.brochure_url} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="text-blue-600 hover:text-blue-800"
                  >
                    View Brochure
                  </a>
                  <button
                    type="button"
                    onClick={() => updateFormData({ brochure_url: '' })}
                    className="text-red-500 hover:text-red-700"
                  >
                    <XMarkIcon className="w-5 h-5" />
                  </button>
                </div>
              ) : (
                <div className="flex items-center">
                  <button
                    type="button"
                    onClick={() => brochureInputRef.current?.click()}
                    className="inline-flex items-center px-4 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
                  >
                    <DocumentTextIcon className="-ml-1 mr-2 h-5 w-5 text-gray-400" />
                    Upload Brochure
                  </button>
                </div>
              )}
              <input
                ref={brochureInputRef}
                type="file"
                accept=".pdf,.doc,.docx"
                className="hidden"
                onChange={(e) => {
                  if (e.target.files && e.target.files[0]) {
                    handleUploadBrochure(e.target.files[0]);
                  }
                }}
              />
            </div>
          </div>
          
          {/* Upload Status */}
          {uploadStatus && (
            <div className={`p-3 rounded-md ${
              uploadStatus.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'
            }`}>
              {uploadStatus.message}
            </div>
          )}
          
          {uploading && (
            <div className="p-3 rounded-md bg-blue-50 text-blue-700 flex items-center">
              <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-blue-700" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              Uploading...
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Project Description */}
        <div className="md:col-span-2">
          <label className="block text-sm font-medium text-gray-700 mb-1">Project Description</label>
          <div className="relative">
            <DocumentTextIcon className="w-5 h-5 absolute left-3 top-3 text-gray-400" />
            <textarea
              name="description"
              value={formData.description}
              onChange={handleChange}
              rows={4}
              className={`pl-10 pr-3 py-2 w-full rounded-lg border ${errors.description ? 'border-red-400' : 'border-gray-300'} focus:ring-green-500 focus:border-green-500`}
              placeholder="Describe the project..."
            />
          </div>
          {errors.description && <p className="text-xs text-red-500 mt-1">{errors.description}</p>}
        </div>
        {/* Project Highlights */}
        <div className="md:col-span-2">
          <label className="block text-sm font-medium text-gray-700 mb-1">Project Highlights <span className="text-xs text-gray-400">(one per line)</span></label>
          <textarea
            name="project_highlights"
            value={formData.project_highlights.join('\n')}
            onChange={handleChange}
            rows={3}
            className={`pr-3 py-2 w-full rounded-lg border ${errors.project_highlights ? 'border-red-400' : 'border-gray-300'} focus:ring-green-500 focus:border-green-500`}
            placeholder="e.g. Prime location\n24/7 Security\nSwimming Pool"
          />
          {errors.project_highlights && <p className="text-xs text-red-500 mt-1">{errors.project_highlights}</p>}
        </div>
        {/* EMI Details */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">EMI Amount (₹)</label>
          <input
            type="number"
            name="emi_details.amount"
            value={formData.emi_details.amount || ''}
            onChange={handleChange}
            className={`pr-3 py-2 w-full rounded-lg border ${errors.emi_details ? 'border-red-400' : 'border-gray-300'} focus:ring-green-500 focus:border-green-500`}
            placeholder="EMI amount"
            min={0}
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">EMI Duration (years)</label>
          <input
            type="number"
            name="emi_details.duration"
            value={formData.emi_details.duration || ''}
            onChange={handleChange}
            className={`pr-3 py-2 w-full rounded-lg border ${errors.emi_details ? 'border-red-400' : 'border-gray-300'} focus:ring-green-500 focus:border-green-500`}
            placeholder="Duration in years"
            min={0}
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">EMI Interest Rate (%)</label>
          <input
            type="number"
            name="emi_details.interest_rate"
            value={formData.emi_details.interest_rate || ''}
            onChange={handleChange}
            className={`pr-3 py-2 w-full rounded-lg border ${errors.emi_details ? 'border-red-400' : 'border-gray-300'} focus:ring-green-500 focus:border-green-500`}
            placeholder="Interest rate"
            min={0}
            step="0.01"
          />
        </div>
      </div>
      
      <div className="flex justify-between pt-4">
        <button
          type="button"
          onClick={onBack}
          className="inline-flex items-center px-6 py-2 bg-gray-200 text-gray-700 font-semibold rounded-lg shadow hover:bg-gray-300 transition-colors focus:outline-none focus:ring-2 focus:ring-green-500"
        >
          <ArrowLeftIcon className="w-5 h-5 mr-2" />
          Back
        </button>
        <button
          type="submit"
          className="inline-flex items-center px-6 py-2 bg-green-600 text-white font-semibold rounded-lg shadow hover:bg-green-700 transition-colors focus:outline-none focus:ring-2 focus:ring-green-500"
        >
          Next
          <ArrowRightIcon className="w-5 h-5 ml-2" />
        </button>
      </div>
    </form>
  );
};

export default ProjectDetails;
